440	                .filter(|s| !s.is_empty())
441	                .ok_or_else(|| eco_format!("version number is missing {kind} version"))?;
442	            part.parse::<u32>()
443	                .map_err(|_| eco_format!("`{part}` is not a valid {kind} version"))
444	        };
