447	        let minor = next("minor")?;
448	        let patch = next("patch")?;
449	        if let Some(rest) = parts.next() {
450	            Err(eco_format!("version number has unexpected fourth component: `{rest}`"))?;
451	        }
452	
453	        Ok(Self { major, minor, patch })
454	    }
